 <?php if($tab==='ai'): ?><script>
 document.querySelectorAll('[data-copy-target]').forEach(function(button) {
  button.addEventListener('click', async function() {
   var field = document.getElementById(button.getAttribute('data-copy-target'));
   if (!field) return;
   field.select();
   try {
    if (navigator.clipboard && navigator.clipboard.writeText) await navigator.clipboard.writeText(field.value);
    else if (!document.execCommand('copy')) throw new Error('copy unavailable');
    button.textContent = 'Tersalin';
   } catch (error) { button.textContent = 'Teks dipilih'; }
  });
 });
 </script><?php endif; ?>
